        <div class="col-md-5"><label for="shape" class="form-label">Shape <span class="text-danger">*</span></label><select id="shape" name="shape" class="form-select"><?php foreach (BoxType::SHAPES as $value => $label): ?><option value="<?= e($value) ?>" <?= ($box['shape'] ?? 'Box') === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div>
