        <div class="col-6 col-md-4" id="widthWrap"><label for="width_cm" class="form-label">Width (cm)</label><input id="width_cm" name="width_cm" type="number" inputmode="decimal" min="0.01" max="2000" step="0.01" class="form-control" value="<?= e((string) ($box['width_cm'] ?? '')) ?>"></div>
        <div class="col-6 col-md-4"><label for="height_cm" class="form-label">Height (cm)</label><input id="height_cm" name="height_cm" type="number" inputmode="decimal" min="0.01" max="2000" step="0.01" class="form-control" value="<?= e((string) ($box['height_cm'] ?? '')) ?>" required></div>
        <div class="col-6 col-md-4"><label for="weight_kg" class="form-label">Weight per item (kg)</label><input id="weight_kg" name="weight_kg" type="number" inputmode="decimal" min="0.001" step="0.001" class="form-control" value="<?= e((string) ($box['weight_kg'] ?? '')) ?>" required></div>
        <div class="col-12"><div class="form-check"><input id="can_tilt" name="can_tilt" type="checkbox" class="form-check-input" <?= !empty($box['can_tilt']) ? 'checked' : '' ?>><label for="can_tilt" class="form-check-label">May be placed on its side</label><div class="form-text">Leave this off to keep the package upright. The planner can still turn it horizontally.</div></div></div>
        <div class="col-12"><div class="form-check form-switch"><input id="is_active" name="is_active" type="checkbox" class="form-check-input" <?= !$box || $box['is_active'] ? 'checked' : '' ?>><label for="is_active" class="form-check-label">Active box type</label></div></div>
    </div>
    <div class="form-actions mt-4"><button class="btn btn-primary" type="submit"><i class="bi bi-check2 me-1" aria-hidden="true"></i> Save box type</button><a class="btn btn-outline-secondary" href="<?= e(url('boxes')) ?>">Cancel</a></div>
